.darma-loader-tw-caret-blink { display: inline-flex; align-items: center; gap: calc(var(--loader-size, 170px) * .03); width: var(--loader-size, 170px); }
.darma-loader-tw-caret-blink .darma-loader-tw-caret-blink__text { height: calc(var(--loader-size, 170px) * .11); border-radius: calc(var(--loader-size, 170px) * .03); background: color-mix(in srgb, var(--loader-color, #22c55e) 32%, transparent); animation: darma-loader-tw-caret-blink-twType calc(var(--loader-speed, 1s) * 2.4) steps(14) infinite; }
.darma-loader-tw-caret-blink .darma-loader-tw-caret-blink__caret { flex: none; width: calc(var(--loader-size, 170px) * .03); height: calc(var(--loader-size, 170px) * .17); background: var(--loader-color, #22c55e); animation: darma-loader-tw-caret-blink-twCaret calc(var(--loader-speed, 1s) * .8) steps(1) infinite; }
@keyframes darma-loader-tw-caret-blink-twType { 0% { width: 6%; } 60%, 100% { width: 78%; } }
@keyframes darma-loader-tw-caret-blink-twCaret { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0; } }

